pub fn is_identifier(a: Ast<'_>, node: NodeId) -> bool {
    node.kind(a) == Kind::Identifier
}

pub fn is_private_identifier(a: Ast<'_>, node: NodeId) -> bool {
    node.kind(a) == Kind::PrivateIdentifier
}

pub fn is_qualified_name(a: Ast<'_>, node: NodeId) -> bool {
    node.kind(a) == Kind::QualifiedName
}

pub fn is_computed_property_name(a: Ast<'_>, node: NodeId) -> bool {
    node.kind(a) == Kind::ComputedPropertyName
}

pub fn is_decorator(a: Ast<'_>, node: NodeId) -> bool {
    node.kind(a) == Kind::Decorator
}

